import sys
from math import atan2

def ccw(p1, p2, p3):
    return (p2[0] - p1[0]) * (p3[1] - p1[1]) - (p2[1] - p1[1]) * (p3[0] - p1[0])

def solve():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    points = [(int(input[i*2+1]), int(input[i*2+2])) for i in range(n)]
    s = input[n*2+1]

    angles = sorted((atan2(y, x), i) for i, (x, y) in enumerate(points))
    start_index = angles[0][1]
    used = [False] * n
    used[start_index] = True
    result = [start_index + 1]
    current_point = start_index

    for turn in s:
        next_point = None
        best_angle = None
        for i, (x, y) in enumerate(points):
            if not used[i]:
                angle = atan2(y - points[current_point][1], x - points[current_point][0])
                if (turn == 'L' and angle > 0) or (turn == 'R' and angle < 0):
                    if best_angle is None or (turn == 'L' and angle > best_angle) or (turn == 'R' and angle < best_angle):
                        best_angle = angle
                        next_point = i
        if next_point is None:
            print(-1)
            return
        used[next_point] = True
        result.append(next_point + 1)
        current_point = next_point

    for i in range(n):
        if not used[i]:
            result.append(i + 1)
            break

    for i in range(1, n-1):
        if ccw(points[result[i-1]-1], points[result[i]-1], points[result[i+1]-1]) * (1 if s[i-1] == 'L' else -1) <= 0:
            print(-1)
            return

    print(' '.join(map(str, result)))

solve()
